{"command": "# Check releases index for available .NET versions
curl -s https://dotnetcli.azureedge.net/dotnet/release-metadata/releases-index.json | python3 -c "
import json,sys
data=json.load(sys.stdin)
for r in data.get('releases-index',[]):
    v = r.get('channel-version','')
    if float(v) >= 9.0:
        print(f\"{v} | support: {r.get('support-phase','')} | latest-sdk: {r.get('latest-sdk','')}\")" 2>/dev/null || echo "Failed to parse"", "description": "Check .NET releases index"}
